pub fn apply_source_input_scale_bias_clamp(
    state: &mut SourceInputScaleBiasClampState,
    raw: f32,
    mapping: &SourceAlphaMapping,
    delta: f32,
) -> f32 {
    if !mapping.source_semantics {
        return raw;
    }
    let mut target = raw;
    if mapping.map_range {
        let divisor = mapping.input_max - mapping.input_min;
        let percent = if divisor.abs() <= 1.0e-8 {
            if raw >= mapping.input_max { 1.0 } else { 0.0 }
        } else {
            (raw - mapping.input_min) / divisor
        };
        target = mapping.output_min + (mapping.output_max - mapping.output_min) * percent;
    }
    target = target * mapping.scale + mapping.bias;
    if mapping.clamp_result {
        target = target.clamp(mapping.clamp_min, mapping.clamp_max);
    }
    if mapping.interpolate_result {
        if state.initialized {
            let speed = if target >= state.value {
                mapping.interpolate_speed_increasing
            } else {
                mapping.interpolate_speed_decreasing
            };
            target = f_interp_to(state.value, target, delta, speed);
        }
        state.value = target;
    }
    state.initialized = true;
    target
}

fn source_blend_alpha(
    state: &mut SourceBlendState,
    raw: f32,
    mapping_max: f32,
    mapping: &SourceAlphaMapping,
    alpha_scale: f32,
    alpha_bias: f32,
    minimum: f32,
    maximum: f32,
    increasing_speed: f32,
    decreasing_speed: f32,
    delta: f32,
) -> f32 {
    if mapping.source_semantics {
        let mut mapping_state = SourceInputScaleBiasClampState {
            initialized: state.initialized,
            value: state.value,
        };
        let target = apply_source_input_scale_bias_clamp(&mut mapping_state, raw, mapping, delta);
        state.initialized = mapping_state.initialized;
        state.value = mapping_state.value;
        return (target * alpha_scale + alpha_bias).clamp(0.0, 1.0);
    }
    let mapped = if mapping_max > f32::EPSILON {
        (raw / mapping_max).clamp(0.0, 1.0)
    } else {
        raw
    };
    let target = mapped.clamp(minimum, maximum);
    if !state.initialized {
        state.initialized = true;
        state.value = target;
        return (target * alpha_scale + alpha_bias).clamp(0.0, 1.0);
    }
    let speed = if target >= state.value {
        increasing_speed
    } else {
        decreasing_speed
    };
    state.value = f_interp_to(state.value, target, delta, speed);
    (state.value * alpha_scale + alpha_bias).clamp(0.0, 1.0)

impl SourceMeshSpaceAdditiveNode {
    fn alpha_input(&self, ctx: &NodeContext) -> Result<f32, GraphError> {
        Ok(if self.use_constant_alpha {
            self.constant_alpha
        } else if self.expose_alpha_pin {
            ctx.data_back(self.alpha_pin.clone())
                .and_then(|value| value.as_f32())
                .or_else(|_| global_f32_or_root_default(ctx, &self.alpha_key))?
        } else {
            global_f32_or_root_default(ctx, &self.alpha_key)?
        })
    }
}

impl NodeLike for SourceMeshSpaceAdditiveNode {
    fn update(&self, mut ctx: NodeContext) -> Result<(), GraphError> {
        let mut base = ctx.data_back("Base")?.into_pose()?;
        let raw = self.alpha_input(&ctx)?;
        let delta = delta_seconds(&ctx)?;
        let alpha = source_blend_alpha(
            ctx.state_mut::<SourceBlendState>()?,
            raw,
            0.0,
            &self.mapping,
            self.alpha_scale,
            self.alpha_bias,
            self.minimum_alpha,
            self.maximum_alpha,
            self.increasing_speed,
            self.decreasing_speed,
            delta,
        );
        if let Some(skeleton) = ctx
            .graph_context
            .resources
            .skeleton_assets
            .get(&base.skeleton)
        {
            materialize_missing_reference_bones(&mut base, skeleton);
        }
        let additive_is_relevant = alpha > 1e-5;
        if additive_is_relevant {
            let additive = crate::extensions::interruptible_fsm::with_machine_weight(alpha,
                || ctx.data_back("Additive"))?.into_pose()?;
            if ctx
                .graph_context
                .resources
                .skeleton_assets
                .get(&base.skeleton)
                .is_none()
            {
                base.skeleton = additive.skeleton.clone();
            }
            let skeleton = ctx
                .graph_context
                .resources
                .skeleton_assets
                .get(&base.skeleton)
                .ok_or(GraphError::SkeletonMissing(ctx.node_id))?;
            apply_mesh_space_additive(&mut base, &additive, alpha, skeleton);
        }
        ctx.set_time(base.timestamp);
        ctx.set_data_fwd("Pose", base);
        let base_context = pose_input_context_state(&ctx, "Base");
        let additive_context = additive_is_relevant
            .then(|| pose_input_context_state(&ctx, "Additive")).flatten();
        let context = blend_animation_contexts([
            (base_context.unwrap_or_default(), 1.0),
            (additive_context.unwrap_or_default(), alpha),
        ]);
        ctx.state_mut::<SourceBlendState>()?.context = context;
        Ok(())
    }

    fn spec(&self, mut ctx: SpecContext) -> Result<(), GraphError> {
        ctx.add_input_data("Base", DataSpec::Pose)
            .add_input_data("Additive", DataSpec::Pose);

pub fn apply_mesh_space_additive(
    base: &mut Pose,
    additive: &Pose,
    alpha: f32,
    skeleton: &Skeleton,
) {
    if alpha.abs() <= ALPHA_THRESHOLD {
        return;
    }

    materialize_missing_reference_bones(base, skeleton);

    for (bone, additive_index) in &additive.paths {
        let additive_bone = &additive.bones[*additive_index];
        if let Some(base_index) = base.paths.get(bone).copied() {
            merge_non_rotation(&mut base.bones[base_index], additive_bone, alpha);
        } else {
            let mut base_bone = skeleton
                .default_transforms(*bone)
                .map(|transform| BonePose {
                    translation: Some(transform.local.translation),
                    rotation: Some(transform.local.rotation),
                    scale: Some(transform.local.scale),
                    weights: None,
                })
                .unwrap_or_default();
            merge_non_rotation(&mut base_bone, additive_bone, alpha);
            base.add_bone(base_bone, *bone);
        }
    }

    let hierarchy = hierarchy_order(skeleton);
    let mut mesh_rotations: HashMap<bevy_animation_graph::core::pose::BoneId, Quat> =
        HashMap::default();
    for bone in &hierarchy {
        let local = base_local_rotation(base, skeleton, *bone);
        let rotation = skeleton
            .parent(bone)
            .and_then(|parent| mesh_rotations.get(&parent).copied())
            .map(|parent| parent * local)
            .unwrap_or(local);
        mesh_rotations.insert(*bone, rotation);
    }

    for bone in &hierarchy {
        if let (Some(rotation), Some(additive_rotation)) = (
            mesh_rotations.get(bone).copied(),
            additive_rotation(additive, *bone),
        ) {
            mesh_rotations.insert(
                *bone,
                blend_additive_rotation(rotation, additive_rotation, alpha),
            );
        }
    }

    for bone in hierarchy.iter().rev() {
        let Some(rotation) = mesh_rotations.get(bone).copied() else {
            continue;
        };
        let local = skeleton
            .parent(bone)
            .and_then(|parent| mesh_rotations.get(&parent).copied())
            .map(|parent| parent.inverse() * rotation)
            .unwrap_or(rotation)
            .normalize();
        if let Some(base_index) = base.paths.get(bone).copied() {
            base.bones[base_index].rotation = Some(local);
        }
    }

    base.root_motion = merge_root_motion(
        base.root_motion.clone(),
        additive.root_motion.clone(),
        alpha,
    );
}

pub fn source_input_data(ctx: &NodeContext, key: &str) -> Option<DataValue> {
    let arena = ctx.graph_context.context_arena.get_ref();
    let state = arena
        .get_toplevel()
        .node_states
        .get::<SourceInstanceProperties>(NodeId::default(), StateKey::Default)
        .ok();
    source_property_value(
        state,
        ctx.graph_context.frame_index(),
        key,
        ctx.graph_context
            .global_input_data
            .get(&format!("source_frame_input.{key}")),
    )
    .or_else(|| ctx.graph_context.global_input_data.get(key))
    .cloned()
}

fn source_property_value<'a>(
    state: Option<&'a SourceInstanceProperties>,
    frame: u64,
    key: &str,
    input: Option<&'a DataValue>,
) -> Option<&'a DataValue> {
    if state.is_none_or(|state| state.write_frames.get(key) != Some(&frame)) && input.is_some() {
        return input;
    }
    state.and_then(|state| state.values.get(key)).or(input)
}

pub fn set_source_frame_input(
    player: &mut bevy_animation_graph::core::animation_graph_player::AnimationGraphPlayer,
    key: &str,
    value: impl Into<DataValue>,
) {
    player.set_global_input_data(format!("source_frame_input.{key}"), value);
}

pub fn source_player_property<'a>(
    player: &'a bevy_animation_graph::core::animation_graph_player::AnimationGraphPlayer,
    key: &str,
) -> Option<&'a DataValue> {
    let arena = player.get_context_arena();
    let state = arena.and_then(|arena| {
        arena
            .get_toplevel()
            .node_states
            .get::<SourceInstanceProperties>(NodeId::default(), StateKey::Default)
            .ok()
    });
    source_property_value(
        state,
        arena.map_or(0, |arena| arena.frame_index()),
        key,
        player.get_global_input_data(format!("source_frame_input.{key}")),
    )
}
